<?php declare(strict_types=1);require_once __DIR__.'/../../../bootstrap/app.php';use App\Services\Auth;use App\Services\OfferService;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('OFFER_VIEW_OWN');$id=(int)($_GET['id']??0);$errors=[];$o=OfferService::ownFind($id);if(!$o){http_response_code(404);exit('Offer not found.');}if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';else try{OfferService::respond($id,(string)($_POST['action']??''),isset($_POST['counter_amount_tzs'])?(float)$_POST['counter_amount_tzs']:null,(string)($_POST['note']??''),(int)Auth::user()['id']);header('Location: '.Url::to('carrier/offers/view.php?id='.$id.'&responded=1'));exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}$o=OfferService::ownFind($id);}$pageTitle='Transport Offer';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1><?=h($o['offer_thread_ref'].' · version '.$o['version_no'])?></h1><p><?=h($o['load_ref'].' · '.$o['origin_city'].' → '.$o['destination_city'])?></p></div><span class="badge"><?=h($o['offer_status'])?></span></div><?php if(isset($_GET['responded'])):?><div class="success">Offer response recorded.</div><?php endif;foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?><div class="grid"><div class="card"><h3>Company price</h3><p><strong>TZS <?=h(number_format((float)$o['offered_amount_tzs'],2))?></strong></p><p>USD <?=h(number_format((float)$o['offered_amount_usd'],2))?></p><details><summary>Price explanation</summary><p><?=nl2br(h($o['price_breakdown']?:'No additional price explanation'))?></p></details></div><div class="card"><h3>Resource</h3><p><?=h($o['registration_number'].' · '.$o['make_name'].' '.$o['model_name'])?></p><p><?=h('Driver '.$o['driver_name'])?></p></div><div class="card"><h3>Deadline</h3><p><?=h($o['expires_at'])?> UTC</p><p>Offers expire after 24 hours.</p></div></div><?php if($o['offer_status']==='sent'&&Auth::can('OFFER_RESPOND_OWN')):?><form method="post" class="card" style="margin-top:18px"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><div class="field"><label>Counteroffer amount (TZS, required only for counter)</label><input type="number" min="1" step="0.01" name="counter_amount_tzs"></div><div class="field"><label>Optional response note</label><textarea name="note" maxlength="2000" rows="4"></textarea></div><div class="actions"><button class="button" name="action" value="accept">Accept</button><button class="button secondary" name="action" value="counter">Counteroffer</button><button class="button secondary" name="action" value="decline">Decline</button></div></form><?php endif;?><p><a href="<?=h(Url::to('carrier/offers/index.php'))?>">← Back to offers</a></p><?php require BASE_PATH.'/app/Views/layout/footer.php';
